        public void Execute(ExecutionResult result)
        {
            var h = Object.FindFirstObjectByType<WebClientHud>();
            h.OperatorControls.DeselectVehicle();
            foreach (var d in h.GetComponentsInChildren<Dropdown>(true))
                if (d.name == "Dispatch Policy Dropdown")
                    d.Show();
            ScreenCapture.CaptureScreenshot("artifacts/high_speed_drive/garage-dropdown-charging.png");
            foreach (var c in Object.FindObjectsByType<UnityAutonomousClient>(FindObjectsSortMode.None))
